ALTER TABLE "companies" DROP CONSTRAINT "companies_grievance_provenance";--> statement-breakpoint
ALTER TABLE "companies" DROP CONSTRAINT "companies_fictional_example_only";--> statement-breakpoint
ALTER TABLE "companies" DROP CONSTRAINT "companies_real_not_example";--> statement-breakpoint
ALTER TABLE "companies" ADD COLUMN "grievance_channel" text DEFAULT 'email' NOT NULL;--> statement-breakpoint
ALTER TABLE "companies" ADD COLUMN "grievance_form_url" text;--> statement-breakpoint
ALTER TABLE "companies" ADD COLUMN "self_serve_url" text;--> statement-breakpoint
ALTER TABLE "companies" ADD CONSTRAINT "companies_channel_valid" CHECK ("companies"."grievance_channel" in ('email', 'web_form'));--> statement-breakpoint
ALTER TABLE "companies" ADD CONSTRAINT "companies_channel_fields" CHECK (("companies"."grievance_channel" = 'email' AND "companies"."grievance_form_url" IS NULL) OR ("companies"."grievance_channel" = 'web_form' AND "companies"."grievance_email" IS NULL));--> statement-breakpoint
ALTER TABLE "companies" ADD CONSTRAINT "companies_verified_has_contact" CHECK ("companies"."grievance_status" <> 'verified' OR ("companies"."grievance_channel" = 'email' AND "companies"."grievance_email" IS NOT NULL) OR ("companies"."grievance_channel" = 'web_form' AND "companies"."grievance_form_url" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "companies" ADD CONSTRAINT "companies_urls_https" CHECK (("companies"."grievance_form_url" IS NULL OR "companies"."grievance_form_url" ~ '^https://[^[:space:]]+$') AND ("companies"."self_serve_url" IS NULL OR "companies"."self_serve_url" ~ '^https://[^[:space:]]+$'));--> statement-breakpoint
ALTER TABLE "companies" ADD CONSTRAINT "companies_grievance_provenance" CHECK (("companies"."grievance_email" IS NULL AND "companies"."grievance_form_url" IS NULL) OR ("companies"."grievance_source" IS NOT NULL AND "companies"."grievance_verified_on" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "companies" ADD CONSTRAINT "companies_fictional_example_only" CHECK (NOT "companies"."is_fictional" OR (("companies"."grievance_email" IS NULL OR "companies"."grievance_email" ~* '@example\.com$') AND ("companies"."grievance_form_url" IS NULL OR "companies"."grievance_form_url" ~* '^https://([a-z0-9-]+\.)*example\.com(/|$)') AND ("companies"."self_serve_url" IS NULL OR "companies"."self_serve_url" ~* '^https://([a-z0-9-]+\.)*example\.com(/|$)')));--> statement-breakpoint
ALTER TABLE "companies" ADD CONSTRAINT "companies_real_not_example" CHECK ("companies"."is_fictional" OR (("companies"."grievance_email" IS NULL OR "companies"."grievance_email" !~* '@example\.com$') AND ("companies"."grievance_form_url" IS NULL OR "companies"."grievance_form_url" !~* '^https://([a-z0-9-]+\.)*example\.com(/|$)') AND ("companies"."self_serve_url" IS NULL OR "companies"."self_serve_url" !~* '^https://([a-z0-9-]+\.)*example\.com(/|$)')));